def build_html_tree(self):
    from grab.base import GLOBAL_STATE
    if self._lxml_tree is None:
        body = self.unicode_body().strip()
        if self._grab_config['lowercased_tree']:
            body = body.lower()
        body = RE_XML_DECLARATION.sub('', body)
        if not body:
            body = '<html></html>'
        start = time.time()
        try:
            self._lxml_tree = self._build_dom(body, 'html')
        except Exception as ex:
            if isinstance(ex, ParserError) and 'Document is empty' in str(ex) and ('<html' not in body):
                body = '<html>%s</html>' % body
                self._lxml_tree = self._build_dom(body, 'html')
            elif isinstance(ex, TypeError) and "object of type 'NoneType' has no len" in str(ex) and ('<html' not in body):
                body = '<html>%s</html>' % body
                self._lxml_tree = self._build_dom(body, 'html')
            else:
                raise
        GLOBAL_STATE['dom_build_time'] += time.time() - start
    return self._lxml_tree

